mapper.select:
SELECT JSON_UNQUOTE(JSON_EXTRACT(u.original_object_ref,'$.object_key')) AS object_key,
  JSON_UNQUOTE(JSON_EXTRACT(u.original_object_ref,'$.object_version')) AS object_version,
  JSON_UNQUOTE(JSON_EXTRACT(u.original_object_ref,'$.sha256')) AS sha256
FROM source_upload_result u WHERE u.source_version=#{sourceVersion}
  AND JSON_UNQUOTE(JSON_EXTRACT(u.original_object_ref,'$.object_key'))!=#{objectKey}
ORDER BY u.upload_id

mapper.update:
UPDATE deletion_item SET lease_expires_at=TIMESTAMPADD(SECOND,#{leaseSeconds},#{now})
WHERE item_id=#{itemId} AND status='RUNNING' AND lease_owner=#{workerId}
  AND lease_generation=#{generation} AND lease_expires_at>#{now} AND revision=#{expectedRevision}

UPDATE deletion_item SET execution_evidence=#{evidence},updated_at=#{now}
WHERE item_id=#{itemId} AND lease_owner=#{workerId} AND lease_generation=#{generation}
  AND lease_expires_at>#{now} AND status='RUNNING' AND revision=#{expectedRevision}

UPDATE deletion_item SET worker_receipt=#{receipt},updated_at=#{now}
WHERE item_id=#{itemId} AND lease_owner=#{workerId} AND lease_generation=#{generation}
  AND lease_expires_at>#{now} AND status='RUNNING' AND revision=#{expectedRevision}

UPDATE deletion_item SET lease_owner=NULL,lease_expires_at=NULL,updated_at=#{now}
WHERE item_id=#{itemId} AND lease_owner=#{workerId} AND lease_generation=#{generation}
  AND lease_expires_at>#{now} AND status='RUNNING' AND revision=#{expectedRevision}

mapper.select:
SELECT (SELECT COUNT(*) FROM source_chunk c WHERE c.source_version=#{sourceVersion}
  AND c.parse_version=#{parseVersion} AND (LENGTH(c.raw_text)>0 OR JSON_LENGTH(c.locator)>0))
  +(SELECT COUNT(*) FROM content_node n WHERE n.source_version=#{sourceVersion}
  AND n.parse_version=#{parseVersion} AND (JSON_LENGTH(n.content_ref)>0 OR JSON_LENGTH(n.locator)>0))
